window.RP_SESSION={"id":"S-16c0b3797d2b","messages":[{"id":"RP-0194128","time":"2026-07-17T02:38:00+09:00","room":"RP","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"조용히 눈을 감아본다. 점차 아버지라 부르던 해적을 떠나보내던 그날의 기억이, 기억의 해수면 위로 떠오른다.\n\n수장된 몸이 바다의 품 안에서 차츰 눅눅해지며, 느리게 젖어들어 이윽고 사라진다.\n\n반사되는 햇빛 아래로, 사라져 버렸단 말입니다. 그가 사랑했던 바다로. 자유로운 해적이라 불리었던 그 사내가, 깊고 어두운 그 바다 아래로 사라진 것입니다.\n\n아버지는 가끔 거친 얼굴 속에 숨겨져 있던 순수한 소년의 눈빛으로 바다를 바라보고 계셨습니다. 마치 마법에 걸린 것처럼, 조용히 바다를 바라보고 계셨습니다.\n\n나는 가끔, 그날의 바다를 생각하며 눈을 감습니다. 거칠었던 그 사내가 영원히 떠나간 부드러운 바다를, 떠올리고는 합니다. 마법에 걸린 것처럼.\n\n아버지가 사랑했던 바다를.\n\n내가 사랑하는 바다를.","characters":["P-8b864b607de4"]},{"id":"RP-0194129","time":"2026-07-17T02:38:00+09:00","room":"RP","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-8b864b607de4"]},{"id":"RP-0194130","time":"2026-07-17T02:38:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
